const diagnosticNodeSpans = new WeakMap<Page, Array<Record<string, unknown>>>();
async function diagnosticBoundary(page: Page, label: string) {
  const nodeSentAt = performance.now();
  const browser = await page.evaluate((label) => {
    const at = performance.timeOrigin + performance.now();
    const probe = (globalThis as unknown as { __sheetUrlProbe?: BrowserProbe }).__sheetUrlProbe;
    probe?.diagnosticEvents.push({ kind: "node-boundary", label, at });
    return { epochAt: at, timeOrigin: performance.timeOrigin, monotonicAt: performance.now(), readyState: document.readyState, marks: { ...probe?.marks } };
  }, label);
  const nodeReceivedAt = performance.now();
  return { label, nodeSentAt, nodeReceivedAt, roundTripMs: nodeReceivedAt - nodeSentAt, browser };
}
async function diagnosticStep(page: Page, kind: "action" | "expect", label: string, work: () => Promise<unknown>) {
  const beforeBoundary = await diagnosticBoundary(page, `${label}:before`);
  const nodeStartedAt = performance.now();
  let succeeded = false;
  try {
    await work();
    succeeded = true;
  } finally {
    const nodeFinishedAt = performance.now();
    const afterBoundary = await diagnosticBoundary(page, `${label}:after`);
    const spans = diagnosticNodeSpans.get(page) ?? [];
    spans.push({ kind, label, nodeStartedAt, nodeFinishedAt, durationMs: nodeFinishedAt - nodeStartedAt, succeeded, beforeBoundary, afterBoundary });
    diagnosticNodeSpans.set(page, spans);
  }
}
async function diagnosticWatchDom(page: Page, label: string, locator: Locator) {
  const nodeStartedAt = performance.now();
  const element = await locator.elementHandle();
  if (!element) throw new Error(`Missing diagnostic DOM target: ${label}`);
  const browser = await page.evaluate(({ label, element }) => {
    const state = globalThis as unknown as {
      __sheetUrlDiagnosticTargets?: Array<{ label: string; element: Element; removed: boolean }>;
      __sheetUrlProbe?: BrowserProbe;
    };
    (state.__sheetUrlDiagnosticTargets ??= []).push({ label, element, removed: false });
    const at = performance.timeOrigin + performance.now();
    state.__sheetUrlProbe?.diagnosticEvents.push({ kind: "dom-watch", label, at, connected: element.isConnected });
    return { epochAt: at, timeOrigin: performance.timeOrigin };
  }, { label, element });
  const spans = diagnosticNodeSpans.get(page) ?? [];
  spans.push({ kind: "dom-watch-setup", label, nodeStartedAt, nodeFinishedAt: performance.now(), browser });
  diagnosticNodeSpans.set(page, spans);
}
